fn fetch_pool_state(context: &CliContext, args: PoolStateArgs) -> Result<(), CliError> {
	let address = match &args.address {
		Some(value) => CliContext::pubkey("--address", value)?,
		None => {
			let stake_mint = match &args.stake_mint {
				Some(value) => CliContext::pubkey("--stake_mint", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "pool-state".to_string(),
						seed: "--stake_mint".to_string(),
					});
				}
			};
			let reward_mint = match &args.reward_mint {
				Some(value) => CliContext::pubkey("--reward_mint", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "pool-state".to_string(),
						seed: "--reward_mint".to_string(),
					});
				}
			};
			let seeds: &[&[u8]] = &["pool".as_bytes(), stake_mint.as_ref(), reward_mint.as_ref()];
			Pubkey::find_program_address(seeds, &context.program_address).0
		}
	};
	let data = context.fetch_account(&address)?;
	let value = match staking_rewards_program_client::accounts::PoolState::from_bytes(&data) {
		Ok(account) => pool_state_json(account),
		Err(error) => {
			return Err(CliError::AccountDecode {
				address: address.to_string(),
				message: error.to_string(),
			});
		}
	};
	print_value(context.json, "pool-state", &address, &value);
	Ok(())
}

