fn pool_state_json(account: &staking_rewards_program_client::accounts::PoolStateZc) -> Value {
	json!({
		"admin": account.admin.to_string(),
		"stake_mint": account.stake_mint.to_string(),
		"reward_mint": account.reward_mint.to_string(),
		"total_staked": account.total_staked.get(),
		"reward_index": account.reward_index.get(),
		"paused": account.paused.get(),
		"bump": account.bump,
	})
}

fn position_state_json(
	account: &staking_rewards_program_client::accounts::PositionStateZc,
) -> Value {
	json!({
		"pool": account.pool.to_string(),
		"owner": account.owner.to_string(),
		"staked_amount": account.staked_amount.get(),
		"reward_debt": account.reward_debt.get(),
		"pending_rewards": account.pending_rewards.get(),
		"bump": account.bump,
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
